import sys
from collections import deque

# 链状树的深度可能超过 Python 默认的递归层数。
sys.setrecursionlimit(1_000_000)


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(values):
    # 层序队列格式：依次为每个非空节点分配左、右孩子。
    # null 不入队，末尾缺失的孩子视为 null；不是 2*i+1 下标格式。
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    i = 1
    while queue and i < len(values):
        node = queue.popleft()
        for side in ("left", "right"):
            if i >= len(values):
                break
            value = values[i]
            i += 1
            if value is not None:
                child = TreeNode(value)
                setattr(node, side, child)
                queue.append(child)
    return root


def solve(p, q):
    if p is None or q is None:
        return p is q
    if p.val != q.val:
        return False
    return solve(p.left, q.left) and solve(p.right, q.right)

def main():
    p = build_tree(json.loads(sys.stdin.readline()))
    q = build_tree(json.loads(sys.stdin.readline()))
    answer = solve(p, q)
    print(1 if answer else 0)


