        skip = max(left_take, left_skip) + max(right_take, right_skip)
        return take, skip

    return max(gains(root))

def main():
    root = build_tree(json.loads(sys.stdin.readline()))
    answer = solve(root)
    print(answer)


if __name__ == "__main__":
    main()
